  // -----------------------------
  const DATA = {
    nRows: 550,
    years: [2009,2010,2011,2012,2013,2014,2015,2016,2017,2018,2019],
    genres: ['Fiction','Non Fiction'],
    uniqueBooks: 351,
    uniqueAuthors: 248,
