      {Year:2013, avgPrice:14.6,  avgRating:4.554, avgReviews:13098.14, count:50},
      {Year:2014, avgPrice:14.64, avgRating:4.622, avgReviews:15859.94, count:50},
      {Year:2015, avgPrice:10.42, avgRating:4.648, avgReviews:14233.38, count:50},
      {Year:2016, avgPrice:13.18, avgRating:4.678, avgReviews:14196.00, count:50},
      {Year:2017, avgPrice:11.38, avgRating:4.66,  avgReviews:12888.40, count:50},
      {Year:2018, avgPrice:10.52, avgRating:4.668, avgReviews:13930.42, count:50},
      {Year:2019, avgPrice:10.08, avgRating:4.74,  avgReviews:15898.34, count:50},
    ],
    yoy: [
      {Year:2010, dPrice:-1.92, dRating:-0.026, dReviews:769.5},
      {Year:2011, dPrice: 1.62, dRating: 0.000, dReviews:2621.2},
      {Year:2012, dPrice: 0.20, dRating:-0.026, dReviews:4990.1},
      {Year:2013, dPrice:-0.70, dRating: 0.022, dReviews:7.22},
      {Year:2014, dPrice: 0.04, dRating: 0.068, dReviews:2761.8},
      {Year:2015, dPrice:-4.22, dRating: 0.026, dReviews:-1626.56},
      {Year:2016, dPrice: 2.76, dRating: 0.030, dReviews:-37.38},
