      {Author:'Jeff Kinney', appearances:12, uniqueTitles:12, avgPrice:9.25, avgRating:4.8,   avgReviews:5623.5},
      {Author:'Suzanne Collins', appearances:11, uniqueTitles:5, avgPrice:13.363636363636363, avgRating:4.663636363636363, avgReviews:25302.636363636364},
      {Author:'Rick Riordan', appearances:11, uniqueTitles:10, avgPrice:9.909090909090908, avgRating:4.7727272727272725, avgReviews:4015.3636363636365},
