      {Author:'Stephenie Meyer', appearances:7, uniqueTitles:7, avgPrice:19.857142857142858, avgRating:4.6571428571428575, avgReviews:6294.0},
      {Author:'Dav Pilkey', appearances:7, uniqueTitles:6, avgPrice:6.285714285714286, avgRating:4.9, avgReviews:7356.571428571428},
      {Author:"Bill O'Reilly", appearances:7, uniqueTitles:6, avgPrice:10.571428571428571, avgRating:4.642857142857143, avgReviews:9112.42857142857},
