      {Author:'Eric Carle', appearances:7, uniqueTitles:1, avgPrice:5.0, avgRating:4.9, avgReviews:19546.0},
      {Author:'J.K. Rowling', appearances:6, uniqueTitles:6, avgPrice:20.166666666666668, avgRating:4.45, avgReviews:11755.833333333334},
      {Author:'E L James', appearances:6, uniqueTitles:5, avgPrice:15.333333333333334, avgRating:4.233333333333333, avgReviews:29668.5}
    ]
  };

  // -----------------------------
  // Utility formatting
  // -----------------------------
  const fmtInt = (n) => new Intl.NumberFormat('en-US', {maximumFractionDigits:0}).format(n);
  const fmt1 = (n) => new Intl.NumberFormat('en-US', {maximumFractionDigits:1, minimumFractionDigits:1}).format(n);
  const fmt2 = (n) => new Intl.NumberFormat('en-US', {maximumFractionDigits:2, minimumFractionDigits:2}).format(n);
  const fmt3 = (n) => new Intl.NumberFormat('en-US', {maximumFractionDigits:3, minimumFractionDigits:3}).format(n);
  const fmtUSD = (n) => '$' + new Intl.NumberFormat('en-US', {maximumFractionDigits:2}).format(n);

  // -----------------------------
  // Populate KPI tiles
  // -----------------------------
  document.getElementById('kpiRows').textContent = fmtInt(DATA.nRows);
  document.getElementById('kpiYears').textContent = `Years covered: ${DATA.years[0]}–${DATA.years[DATA.years.length-1]}`;
  document.getElementById('kpiAvgPrice').textContent = fmtUSD(DATA.avgPrice);
  document.getElementById('kpiPriceRange').textContent = `Range: ${fmtUSD(DATA.priceMin)}–${fmtUSD(DATA.priceMax)}`;
  document.getElementById('kpiAvgRating').textContent = fmt3(DATA.avgRating);
  document.getElementById('kpiRatingRange').textContent = `Range: ${fmt1(DATA.ratingMin)}–${fmt1(DATA.ratingMax)}`;
  document.getElementById('kpiAvgReviews').textContent = fmtInt(DATA.avgReviews);
  document.getElementById('kpiReviewsRange').textContent = `Range: ${fmtInt(DATA.reviewsMin)}–${fmtInt(DATA.reviewsMax)}`;
  document.getElementById('kpiCorr').textContent = fmt3(DATA.corrAll);
  document.getElementById('corrInline').textContent = fmt3(DATA.corrAll);

  // -----------------------------
  // Narrative bullets (grounded in computed facts)
  // -----------------------------
  (function fillBullets(){
    const over = document.getElementById('overviewBullets');
    const topLabel = DATA.priceBucketsOverall.labels
      .map((l,i)=>({l,count:DATA.priceBucketsOverall.counts[i]}))
      .sort((a,b)=>b.count-a.count);

    const share = (count) => (100*count/DATA.nRows);
    const top1=topLabel[0], top2=topLabel[1];

    const share2009 = DATA.priceBucketsByYear['2009'].map(c=>c/50);
    const share2019 = DATA.priceBucketsByYear['2019'].map(c=>c/50);
    const idx_20_29 = DATA.priceBucketsOverall.labels.indexOf('20-29');
    const idx_30_49 = DATA.priceBucketsOverall.labels.indexOf('30-49');
    const idx_50p = DATA.priceBucketsOverall.labels.indexOf('50+');

    const bullets = [
      `The bestseller list is concentrated in mid-price bands: $${top1.l} accounts for ${fmt1(share(top1.count))}% of entries and $${top2.l} for ${fmt1(share(top2.count))}% (combined ${fmt1(share(top1.count+top2.count))}%).`,
