    ];
    bullets2.forEach(t=>{ const li=document.createElement('li'); li.textContent=t; genreBullets.appendChild(li); });

    const trendBullets=document.getElementById('trendBullets');
    const y=DATA.byYear;
    const find=(year)=>y.find(d=>d.Year===year);
    const bullets3=[
      `2015 is the major pricing inflection: average price drops from ${fmtUSD(find(2014).avgPrice)} (2014) to ${fmtUSD(find(2015).avgPrice)} (2015), a YoY change of ${fmtUSD(DATA.yoy.find(d=>d.Year===2015).dPrice)} — the largest absolute price shift in the series.`,
