    const recos=[
      {title:'Optimize price for conversion/margin, not for rating lift.', body:`Across all entries, Price vs Rating correlation is weak and negative (Pearson r=${fmt3(DATA.corrAll)}). Treat pricing decisions as revenue levers; protect ratings through content quality and expectation alignment.`},
