bash -lc "cat > /app/output/final_report.html <<'HTML'
<!doctype html>
<html lang="en">
<head>
  <meta charset="utf-8" />
  <meta name="viewport" content="width=device-width, initial-scale=1" />
  <title>Amazon Bestselling Books: Price vs. User Rating Trend Analysis (2009–2019)</title>
  <script src="https://cdn.jsdelivr.net/npm/chart.js@4.4.3/dist/chart.umd.min.js"></script>
  <style>
    :root{
      --bg:#0b1220;
      --text:#e9eefc;
      --muted:#b7c3e6;
      --grid:rgba(255,255,255,.08);
      --accent:#69b3ff;
      --warn:#ffb86b;
      --nf:#69b3ff;
      --fic:#8ef0c5;
      --shadow: 0 10px 24px rgba(0,0,0,.35);
      --radius: 14px;
    }
    *{box-sizing:border-box}
    body{
      margin:0;
      font-family: ui-sans-serif, system-ui, -apple-system, Segoe UI, Roboto, Helvetica, Arial, "Apple Color Emoji", "Segoe UI Emoji";
      background: radial-gradient(1200px 900px at 20% 10%, rgba(105,179,255,.14), transparent 60%),
                  radial-gradient(1100px 800px at 90% 30%, rgba(142,240,197,.12), transparent 55%),
                  var(--bg);
      color:var(--text);
      line-height:1.45;
    }
    header{padding: 34px 22px 18px; max-width: 1200px; margin: 0 auto;}
    h1{margin:0 0 8px; font-size: 28px; letter-spacing:.2px}
    .subtitle{color:var(--muted); margin:0; max-width: 980px}
    .meta{margin-top:10px; color:var(--muted); font-size:13px}

    main{max-width:1200px; margin:0 auto; padding: 10px 22px 44px;}
    .grid{display:grid; gap:14px;}
    .kpi-grid{grid-template-columns: repeat(5, minmax(0,1fr));}
    .two-col{grid-template-columns: 1.2fr .8fr; align-items:start;}
    .three-col{grid-template-columns: repeat(3, minmax(0,1fr));}

    .card{
      background: linear-gradient(180deg, rgba(255,255,255,.03), rgba(255,255,255,.01));
      border: 1px solid rgba(255,255,255,.08);
      border-radius: var(--radius);
      box-shadow: var(--shadow);
      padding: 16px 16px;
    }
    .card h3{margin:0 0 8px; font-size:15px;}

    .kpi{padding:14px 14px; border-radius: 12px; background: rgba(255,255,255,.02); border: 1px solid rgba(255,255,255,.07); min-height: 92px;}
    .kpi .label{color:var(--muted); font-size:12px; margin-bottom:6px}
    .kpi .value{font-size:22px; font-weight:700; letter-spacing:.2px}
    .kpi .note{color:var(--muted); font-size:12px; margin-top:6px}

    .pill{display:inline-flex; align-items:center; gap:8px; border:1px solid rgba(255,255,255,.12); border-radius:999px; padding:6px 10px; font-size:12px; color:var(--muted); background: rgba(255,255,255,.02); white-space:nowrap;}
    .dot{width:10px; height:10px; border-radius:50%}
    .dot.fic{background:var(--fic)}
    .dot.nf{background:var(--nf)}

    .section{margin-top:14px}
    .section-title{display:flex; align-items:flex-end; justify-content:space-between; gap:12px; margin: 10px 2px 10px;}
    .section-title h2{margin:0; font-size:20px}
    .section-title p{margin:0; color:var(--muted); font-size:13px; max-width: 820px}

    .chart-wrap{height: 310px;}
    .chart-wrap.tall{height: 360px;}
    canvas{width:100% !important; height:100% !important;}

    table{width:100%; border-collapse: collapse; font-size:13px}
    th, td{padding:10px 10px; border-bottom: 1px solid rgba(255,255,255,.08); vertical-align: top;}
    th{color:var(--muted); font-weight:600; text-align:left}
    .num{text-align:right; font-variant-numeric: tabular-nums;}

    .callout{border-left: 3px solid var(--accent); padding: 10px 12px; background: rgba(105,179,255,.07); border-radius: 12px;}
    .bullets{margin:0; padding-left: 18px;}
    .bullets li{margin: 6px 0;}
    .muted{color:var(--muted)}

    footer{max-width:1200px; margin:0 auto; padding: 0 22px 28px; color:var(--muted); font-size:12px}

    @media (max-width: 1080px){
      .kpi-grid{grid-template-columns: repeat(2, minmax(0,1fr));}
      .two-col{grid-template-columns: 1fr;}
      .three-col{grid-template-columns: 1fr;}
      .chart-wrap{height: 290px}
    }
  </style>
</head>
<body>
  <header>
    <h1>Amazon Bestselling Books: Price vs. User Rating Trend Analysis (2009–2019)</h1>
    <p class="subtitle">A management-oriented view of pricing vs satisfaction, split by genre, with year-over-year inflections from 2009–2019.</p>
    <div class="meta">Source: 50 Amazon bestsellers per year (2009–2019), 550 entries total.</div>
  </header>

  <main>
    <section class="card">
      <div class="section-title" style="margin-top:0">
        <h2>Executive Summary</h2>
        <p>KPIs and the core relationship between price and user rating.</p>
      </div>
      <div class="grid kpi-grid">
        <div class="kpi"><div class="label">Entries</div><div class="value" id="kpiRows"></div><div class="note" id="kpiYears"></div></div>
        <div class="kpi"><div class="label">Avg Price</div><div class="value" id="kpiAvgPrice"></div><div class="note" id="kpiPriceRange"></div></div>
        <div class="kpi"><div class="label">Avg Rating</div><div class="value" id="kpiAvgRating"></div><div class="note" id="kpiRatingRange"></div></div>
        <div class="kpi"><div class="label">Avg Reviews</div><div class="value" id="kpiAvgReviews"></div><div class="note" id="kpiReviewsRange"></div></div>
        <div class="kpi"><div class="label">Pearson r (Price vs Rating)</div><div class="value" id="kpiCorr"></div><div class="note">Computed on all 550 entries.</div></div>
      </div>

      <div class="grid two-col" style="margin-top:14px">
        <div class="callout">
          <strong>Headline finding:</strong> Price and rating have a <strong>weak negative</strong> relationship across bestsellers (Pearson <span id="corrInline"></span>). Higher-priced titles do not systematically earn higher customer ratings.
        </div>
        <div>
          <div style="display:flex; gap:10px; flex-wrap:wrap">
            <span class="pill"><span class="dot nf"></span>Non Fiction</span>
            <span class="pill"><span class="dot fic"></span>Fiction</span>
          </div>
          <p class="muted" style="margin:10px 0 0">Management implication: optimize price for revenue and conversion; protect satisfaction via positioning, packaging, and content fit rather than premium pricing.</p>
        </div>
      </div>
    </section>

    <section class="section">
      <div class="section-title">
        <h2>1) Bestseller Market Overview (2009–2019)</h2>
        <p>Where the bestseller list sits by price tier and decade-level benchmarks.</p>
      </div>
      <div class="grid two-col">
        <div class="card">
          <h3>Price Segment Mix</h3>
          <div class="chart-wrap"><canvas id="priceBuckets"></canvas></div>
        </div>
        <div class="card">
          <h3>Key takeaways</h3>
          <ul class="bullets" id="overviewBullets"></ul>
        </div>
      </div>
    </section>

    <section class="section">
      <div class="section-title">
        <h2>2) Price vs. User Rating: Correlation Analysis</h2>
        <p>Pearson correlation coefficient plus a scatter visualization.</p>
      </div>
      <div class="grid two-col">
        <div class="card">
          <h3>Scatter (250-entry deterministic sample)</h3>
          <div class="chart-wrap tall"><canvas id="scatterAll"></canvas></div>
          <p class="muted" style="margin:10px 0 0">Correlation values are computed on the full dataset; scatter uses a deterministic sample to stay readable and fast.</p>
        </div>
        <div class="card">
          <h3>Correlation KPIs</h3>
          <table>
            <thead><tr><th>Slice</th><th class="num">Pearson r</th><th>Interpretation</th></tr></thead>
            <tbody id="corrTable"></tbody>
          </table>
        </div>
      </div>
    </section>

    <section class="section">
      <div class="section-title">
        <h2>3) Fiction vs. Non-Fiction: Pricing and Rating Strategies</h2>
        <p>Side-by-side comparison for fast executive scanning.</p>
      </div>
      <div class="grid two-col">
        <div class="card">
          <h3>Genre KPI Comparison</h3>
          <table>
            <thead><tr><th>Genre</th><th class="num">Entries</th><th class="num">Avg Price</th><th class="num">Avg Rating</th><th class="num">Avg Reviews</th><th class="num">Unique Authors</th></tr></thead>
            <tbody id="genreTable"></tbody>
          </table>
        </div>
        <div class="card">
          <h3>Portfolio interpretation</h3>
          <ul class="bullets" id="genreBullets"></ul>
        </div>
      </div>

      <div class="grid three-col" style="margin-top:14px">
        <div class="card"><h3>Avg Price by Year</h3><div class="chart-wrap"><canvas id="linePriceGenre"></canvas></div></div>
        <div class="card"><h3>Avg Rating by Year</h3><div class="chart-wrap"><canvas id="lineRatingGenre"></canvas></div></div>
        <div class="card"><h3>Avg Reviews by Year</h3><div class="chart-wrap"><canvas id="lineReviewsGenre"></canvas></div></div>
      </div>
    </section>

    <section class="section">
      <div class="section-title">
        <h2>4) Year-over-Year Trends in Pricing and Ratings (Most Critical)</h2>
        <p>Trend lines with a delta table to highlight inflection years.</p>
      </div>
      <div class="grid two-col">
        <div class="card">
          <h3>Overall Trend: Price & Rating</h3>
          <div class="chart-wrap tall"><canvas id="trendOverall"></canvas></div>
        </div>
        <div class="card">
          <h3>Inflection Points (YoY deltas)</h3>
          <table>
            <thead><tr><th>Year</th><th class="num">Δ Avg Price</th><th class="num">Δ Avg Rating</th><th class="num">Δ Avg Reviews</th></tr></thead>
            <tbody id="inflectionTable"></tbody>
          </table>
        </div>
      </div>

      <div class="grid two-col" style="margin-top:14px">
        <div class="card"><h3>Overall Trend: Reviews</h3><div class="chart-wrap"><canvas id="trendReviews"></canvas></div></div>
        <div class="card"><h3>Management narrative</h3><ul class="bullets" id="trendBullets"></ul></div>
      </div>
    </section>

    <section class="section">
      <div class="section-title">
        <h2>5) Dominant Authors on the Bestseller List</h2>
        <p>Repeat authorship as a signal for franchise investment and durable demand.</p>
      </div>
      <div class="grid two-col">
        <div class="card"><h3>Top Authors by Appearances</h3><div class="chart-wrap tall"><canvas id="authorsBar"></canvas></div></div>
        <div class="card">
          <h3>Top 15 Author KPIs</h3>
          <table>
            <thead><tr><th>Author</th><th class="num">Appearances</th><th class="num">Unique Titles</th><th class="num">Avg Price</th><th class="num">Avg Rating</th><th class="num">Avg Reviews</th></tr></thead>
            <tbody id="authorTable"></tbody>
          </table>
        </div>
      </div>
    </section>

    <section class="section">
      <div class="section-title">
        <h2>6) Strategic Recommendations</h2>
        <p>Recommendations grounded in the computed results (no speculation).</p>
      </div>
      <div class="card">
        <ol id="recoList" style="margin:0; padding-left:18px"></ol>
      </div>
    </section>
  </main>

  <footer>
    Generated on 2026-04-30 (UTC). All metrics computed from <code>/app/benchmark/data.csv</code>.
  </footer>

  <script src="metrics.js"></script>
  <script>
    const fmtInt = (n) => new Intl.NumberFormat('en-US', {maximumFractionDigits:0}).format(n);
    const fmt1 = (n) => new Intl.NumberFormat('en-US', {maximumFractionDigits:1, minimumFractionDigits:1}).format(n);
    const fmt3 = (n) => new Intl.NumberFormat('en-US', {maximumFractionDigits:3, minimumFractionDigits:3}).format(n);
    const fmtUSD = (n) => '$' + new Intl.NumberFormat('en-US', {maximumFractionDigits:2}).format(n);

    document.getElementById('kpiRows').textContent = fmtInt(DATA.nRows);
    document.getElementById('kpiYears').textContent = 'Years covered: ' + DATA.years[0] + '–' + DATA.years[DATA.years.length-1];
    document.getElementById('kpiAvgPrice').textContent = fmtUSD(DATA.avgPrice);
    document.getElementById('kpiPriceRange').textContent = 'Range: ' + fmtUSD(DATA.minPrice) + '–' + fmtUSD(DATA.maxPrice);
    document.getElementById('kpiAvgRating').textContent = fmt3(DATA.avgRating);
    document.getElementById('kpiRatingRange').textContent = 'Range: ' + fmt1(DATA.minRating) + '–' + fmt1(DATA.maxRating);
    document.getElementById('kpiAvgReviews').textContent = fmtInt(DATA.avgReviews);
    document.getElementById('kpiReviewsRange').textContent = 'Range: ' + fmtInt(DATA.minReviews) + '–' + fmtInt(DATA.maxReviews);
    document.getElementById('kpiCorr').textContent = fmt3(DATA.corrAll);
    document.getElementById('corrInline').textContent = fmt3(DATA.corrAll);

    // Bullets
    (function(){
      const labels = DATA.priceBuckets.labels;
      const counts = DATA.priceBuckets.counts;
      const ranked = labels.map((l,i)=>({l:l,c:counts[i]})).sort((a,b)=>b.c-a.c);
      const share=(c)=>100*c/DATA.nRows;

      const top1=ranked[0], top2=ranked[1];
      const i50=labels.indexOf('50+');
      const i20=labels.indexOf('20-29');
      const share2009=DATA.priceBucketsByYear['2009'].map(c=>c/50);
      const share2019=DATA.priceBucketsByYear['2019'].map(c=>c/50);

      const over=document.getElementById('overviewBullets');
      [
        'Mid-price dominance: $' + top1.l + ' is ' + fmt1(share(top1.c)) + '% and $' + top2.l + ' is ' + fmt1(share(top2.c)) + '% (combined ' + fmt1(share(top1.c+top2.c)) + '%).',
        'Decade benchmarks: avg price ' + fmtUSD(DATA.avgPrice) + '; avg rating ' + fmt3(DATA.avgRating) + '; avg reviews ' + fmtInt(DATA.avgReviews) + '; ' + fmtInt(DATA.uniqueBooks) + ' unique titles; ' + fmtInt(DATA.uniqueAuthors) + ' unique authors.',
        'Premium is rare: only ' + fmtInt(counts[i50]) + ' entries are priced $50+ across 2009–2019.',
        'Shift toward lower price in 2019: $20–$29 share drops from ' + fmt1(100*share2009[i20]) + '% (2009) to ' + fmt1(100*share2019[i20]) + '% (2019); $30–$49 and $50+ are 0 entries in 2019.'
      ].forEach(t=>{const li=document.createElement('li'); li.textContent=t; over.appendChild(li);});

      const gF=DATA.byGenre['Fiction'];
      const gN=DATA.byGenre['Non Fiction'];
      const genreBullets=document.getElementById('genreBullets');
      [
        'Non Fiction prices higher (avg ' + fmtUSD(gN.avgPrice) + ') than Fiction (avg ' + fmtUSD(gF.avgPrice) + ') but rates slightly lower (' + fmt3(gN.avgRating) + ' vs ' + fmt3(gF.avgRating) + ').',
        'Fiction has higher average review volume (' + fmtInt(gF.avgReviews) + ' vs ' + fmtInt(gN.avgReviews) + '), indicating stronger engagement dynamics in Fiction bestsellers.',
        'Both genres show weak negative price–rating correlation (Fiction r=' + fmt3(DATA.corrByGenre['Fiction']) + '; Non Fiction r=' + fmt3(DATA.corrByGenre['Non Fiction']) + ').'
      ].forEach(t=>{const li=document.createElement('li'); li.textContent=t; genreBullets.appendChild(li);});

      const trendBullets=document.getElementById('trendBullets');
      const findYear=(y)=>DATA.byYear.find(d=>d.Year===y);
      const d2015=DATA.yoy.find(d=>d.Year===2015);
      const d2012=DATA.yoy.find(d=>d.Year===2012);
      const d2019=DATA.yoy.find(d=>d.Year===2019);
      [
        '2015 is the major pricing inflection: avg price falls from ' + fmtUSD(findYear(2014).avgPrice) + ' to ' + fmtUSD(findYear(2015).avgPrice) + ' (YoY Δ ' + fmtUSD(d2015.dPrice) + ').',
        '2012 is the major engagement inflection: avg reviews rise by ' + fmtInt(d2012.dReviews) + ' vs 2011 (to ' + fmtInt(findYear(2012).avgReviews) + ').',
        '2019 is the major sentiment inflection: largest YoY rating increase (Δ ' + fmt3(d2019.dRating) + ') and the highest avg rating (' + fmt3(findYear(2019).avgRating) + ').',
        'After 2015, average prices remain lower (≈$10–$13) while average ratings stay high (≥' + fmt3(findYear(2015).avgRating) + ').'
      ].forEach(t=>{const li=document.createElement('li'); li.textContent=t; trendBullets.appendChild(li);});

      const reco=document.getElementById('recoList');
      const topAuthors=DATA.topAuthors.slice(0,5).map(a=>a.Author).join(', ');
      [
        {title:'Optimize price for conversion/margin, not rating lift.', body:'Overall Pearson r is ' + fmt3(DATA.corrAll) + ' (weak negative), so price is not a reliable satisfaction lever.'},
        {title:'Target the $5–$14 corridor for bestseller velocity.', body:'$5–$9 and $10–$14 are the two largest price bands, together ' + fmt1(100*(counts[labels.indexOf('5-9')]+counts[labels.indexOf('10-14')])/DATA.nRows) + '% of entries.'},
        {title:'Premium Non Fiction can work, but justify value explicitly.', body:'Non Fiction averages higher price (' + fmtUSD(gN.avgPrice) + ') with slightly lower ratings than Fiction.'},
        {title:'Invest in Fiction franchises/series to compound engagement.', body:'Fiction averages ' + fmtInt(gF.avgReviews) + ' reviews vs ' + fmtInt(gN.avgReviews) + ' in Non Fiction.'},
        {title:'Treat 2015-style repricing as a playbook option.', body:'The largest price drop (2015, Δ ' + fmtUSD(d2015.dPrice) + ') did not coincide with rating collapse; ratings remained high and improved later.'},
        {title:'Operationalize repeat-author scouting.', body:'Top repeat authors (e.g., ' + topAuthors + ') represent durable catalog assets; use appearances + ratings for prioritization.'}
      ].forEach(r=>{const li=document.createElement('li'); li.innerHTML='<strong>' + r.title + '</strong><div class="muted" style="margin-top:4px">' + r.body + '</div>'; reco.appendChild(li);});
    })();

    // Tables
    (function(){
      const corrBody=document.getElementById('corrTable');
      [
        {slice:'Overall', r: DATA.corrAll, interp:'Weak negative relationship.'},
        {slice:'Fiction', r: DATA.corrByGenre['Fiction'], interp:'Weak negative.'},
        {slice:'Non Fiction', r: DATA.corrByGenre['Non Fiction'], interp:'Weak negative.'}
      ].forEach(x=>{const tr=document.createElement('tr'); tr.innerHTML='<td>' + x.slice + '</td><td class="num">' + fmt3(x.r) + '</td><td>' + x.interp + '</td>'; corrBody.appendChild(tr);});

      const genreBody=document.getElementById('genreTable');
      ['Fiction','Non Fiction'].forEach(g=>{const s=DATA.byGenre[g]; const tr=document.createElement('tr'); tr.innerHTML='<td>' + g + '</td><td class="num">' + fmtInt(s.count) + '</td><td class="num">' + fmtUSD(s.avgPrice) + '</td><td class="num">' + fmt3(s.avgRating) + '</td><td class="num">' + fmtInt(s.avgReviews) + '</td><td class="num">' + fmtInt(s.uniqueAuthors) + '</td>'; genreBody.appendChild(tr);});

      const inflBody=document.getElementById('inflectionTable');
      DATA.yoy.forEach(d=>{const tr=document.createElement('tr'); tr.innerHTML='<td>' + d.Year + '</td><td class="num">' + fmtUSD(d.dPrice) + '</td><td class="num">' + fmt3(d.dRating) + '</td><td class="num">' + fmtInt(d.dReviews) + '</td>'; inflBody.appendChild(tr);});

      const authorBody=document.getElementById('authorTable');
      DATA.topAuthors.forEach(a=>{const tr=document.createElement('tr'); tr.innerHTML='<td>' + a.Author + '</td><td class="num">' + fmtInt(a.appearances) + '</td><td class="num">' + fmtInt(a.uniqueTitles) + '</td><td class="num">' + fmtUSD(a.avgPrice) + '</td><td class="num">' + fmt3(a.avgRating) + '</td><td class="num">' + fmtInt(a.avgReviews) + '</td>'; authorBody.appendChild(tr);});
    })();

    // Charts
    Chart.defaults.color = getComputedStyle(document.documentElement).getPropertyValue('--text').trim();
    Chart.defaults.font.family = getComputedStyle(document.body).fontFamily;
    const gridColor = getComputedStyle(document.documentElement).getPropertyValue('--grid').trim();
    const nfColor = getComputedStyle(document.documentElement).getPropertyValue('--nf').trim();
    const ficColor = getComputedStyle(document.documentElement).getPropertyValue('--fic').trim();
    const accent = getComputedStyle(document.documentElement).getPropertyValue('--accent').trim();

    new Chart(document.getElementById('priceBuckets'), {
      type: 'bar',
      data: {labels: DATA.priceBuckets.labels.map(l=>'$' + l), datasets: [{label:'Entries', data: DATA.priceBuckets.counts, backgroundColor:'rgba(105,179,255,.35)', borderColor:'rgba(105,179,255,.9)', borderWidth:1, borderRadius:8}]},
      options: {plugins:{legend:{display:false}}, scales:{x:{grid:{display:false}}, y:{grid:{color:gridColor}}}}
    });

    new Chart(document.getElementById('scatterAll'), {
      type: 'scatter',
      data: {datasets: [
        {label:'Fiction', data: DATA.scatterSample.filter(p=>p.g==='Fiction').map(p=>({x:p.x,y:p.y})), backgroundColor:'rgba(142,240,197,.55)', borderColor: ficColor, pointRadius:3},
        {label:'Non Fiction', data: DATA.scatterSample.filter(p=>p.g==='Non Fiction').map(p=>({x:p.x,y:p.y})), backgroundColor:'rgba(105,179,255,.45)', borderColor: nfColor, pointRadius:3}
      ]},
      options: {plugins:{title:{display:true, text:'Pearson r (full data): ' + fmt3(DATA.corrAll)}, legend:{position:'bottom'}}, scales:{x:{grid:{color:gridColor}, title:{display:true, text:'Price (USD)'}}, y:{grid:{color:gridColor}, title:{display:true, text:'User Rating'}, suggestedMin:DATA.minRating, suggestedMax:DATA.maxRating}}}
    });

    const years = DATA.byYear.map(d=>d.Year);
    new Chart(document.getElementById('trendOverall'), {
      type:'line',
      data:{labels: years, datasets:[
        {label:'Avg Price (USD)', data: DATA.byYear.map(d=>d.avgPrice), yAxisID:'yPrice', borderColor: accent, backgroundColor:'rgba(105,179,255,.15)', tension:.25, fill:true, pointRadius:3},
        {label:'Avg Rating', data: DATA.byYear.map(d=>d.avgRating), yAxisID:'yRating', borderColor:'rgba(255,184,107,.95)', tension:.25, fill:false, pointRadius:3}
      ]},
      options:{plugins:{legend:{position:'bottom'}}, scales:{x:{grid:{color:gridColor}}, yPrice:{position:'left', grid:{color:gridColor}, title:{display:true, text:'Avg Price'}}, yRating:{position:'right', grid:{display:false}, title:{display:true, text:'Avg Rating'}, min:4.5, max:4.75}}}
    });

    new Chart(document.getElementById('trendReviews'), {
      type:'line',
      data:{labels: years, datasets:[{label:'Avg Reviews', data: DATA.byYear.map(d=>d.avgReviews), borderColor:'rgba(142,240,197,.95)', backgroundColor:'rgba(142,240,197,.12)', tension:.25, fill:true, pointRadius:3}]},
      options:{plugins:{legend:{position:'bottom'}}, scales:{x:{grid:{color:gridColor}}, y:{grid:{color:gridColor}, title:{display:true, text:'Avg Reviews'}}}}
    });

    function lineChart(id, yTitle, seriesKey){
      new Chart(document.getElementById(id), {
        type:'line',
        data:{labels: years, datasets:[
          {label:'Fiction', data: DATA.byYearGenre['Fiction'][seriesKey], borderColor: ficColor, tension:.25, pointRadius:2},
          {label:'Non Fiction', data: DATA.byYearGenre['Non Fiction'][seriesKey], borderColor: nfColor, tension:.25, pointRadius:2}
        ]},
        options:{plugins:{legend:{position:'bottom'}}, scales:{x:{grid:{color:gridColor}}, y:{grid:{color:gridColor}, title:{display:true, text:yTitle}}}}
      });
    }
    lineChart('linePriceGenre','Avg Price (USD)','price');
    lineChart('lineRatingGenre','Avg Rating','rating');
    lineChart('lineReviewsGenre','Avg Reviews','reviews');

    new Chart(document.getElementById('authorsBar'), {
      type:'bar',
      data:{labels: DATA.topAuthors.map(a=>a.Author), datasets:[{label:'Appearances', data: DATA.topAuthors.map(a=>a.appearances), backgroundColor:'rgba(255,184,107,.30)', borderColor:'rgba(255,184,107,.95)', borderWidth:1, borderRadius:8}]},
      options:{indexAxis:'y', plugins:{legend:{display:false}}, scales:{x:{grid:{color:gridColor}}, y:{grid:{display:false}}}}
    });
  </script>
</body>
</html>
