        radial-gradient(1200px 900px at 20% 10%, rgba(105,179,255,.14), transparent 60%),
        radial-gradient(1100px 800px at 90% 30%, rgba(142,240,197,.12), transparent 55%),
        var(--bg);
      color:var(--text);
      line-height:1.45;
    }}
    header{{padding: 34px 22px 18px; max-width: 1200px; margin: 0 auto;}}
    h1{{margin:0 0 8px; font-size: 28px; letter-spacing:.2px}}
