    @media (max-width: 1080px){{
      .kpi-grid{{grid-template-columns: repeat(2, minmax(0,1fr));}}
      .two-col{{grid-template-columns: 1fr;}}
      .three-col{{grid-template-columns: 1fr;}}
      .chart-wrap{{height: 290px}}
    }}
  </style>
</head>
<body>
  <header>
    <h1>Amazon Bestselling Books: Price vs. User Rating Trend Analysis (2009–2019)</h1>
    <p class=\"subtitle\">A management-oriented view of pricing vs satisfaction, split by genre, with year-over-year inflections from 2009–2019.</p>
    <div class=\"meta\">Dataset: 50 bestsellers per year (2009–2019), 550 entries total. All figures computed from <code>data.csv</code>.</div>
  </header>

  <main>
    <section class=\"card\">
      <div class=\"section-title\" style=\"margin-top:0\">
        <h2>Executive Summary</h2>
        <p>KPIs and the core relationship between price and user rating.</p>
      </div>
      <div class=\"grid kpi-grid\">
        <div class=\"kpi\"><div class=\"label\">Entries</div><div class=\"value\" id=\"kpiRows\"></div><div class=\"note\" id=\"kpiYears\"></div></div>
        <div class=\"kpi\"><div class=\"label\">Avg Price</div><div class=\"value\" id=\"kpiAvgPrice\"></div><div class=\"note\" id=\"kpiPriceRange\"></div></div>
        <div class=\"kpi\"><div class=\"label\">Avg Rating</div><div class=\"value\" id=\"kpiAvgRating\"></div><div class=\"note\" id=\"kpiRatingRange\"></div></div>
        <div class=\"kpi\"><div class=\"label\">Avg Reviews</div><div class=\"value\" id=\"kpiAvgReviews\"></div><div class=\"note\" id=\"kpiReviewsRange\"></div></div>
