  <footer>
    Generated on 2026-04-30 (UTC). All metrics computed from <code>/app/benchmark/data.csv</code>.
  </footer>

  <script>
{metrics_js}
  </script>
  <script>
    const fmtInt = (n) => new Intl.NumberFormat('en-US', {{maximumFractionDigits:0}}).format(n);
    const fmt1 = (n) => new Intl.NumberFormat('en-US', {{maximumFractionDigits:1, minimumFractionDigits:1}}).format(n);
    const fmt3 = (n) => new Intl.NumberFormat('en-US', {{maximumFractionDigits:3, minimumFractionDigits:3}}).format(n);
    const fmtUSD = (n) => '$' + new Intl.NumberFormat('en-US', {{maximumFractionDigits:2}}).format(n);

    document.getElementById('kpiRows').textContent = fmtInt(DATA.nRows);
    document.getElementById('kpiYears').textContent = 'Years covered: ' + DATA.years[0] + '–' + DATA.years[DATA.years.length-1];
    document.getElementById('kpiAvgPrice').textContent = fmtUSD(DATA.avgPrice);
    document.getElementById('kpiPriceRange').textContent = 'Range: ' + fmtUSD(DATA.minPrice) + '–' + fmtUSD(DATA.maxPrice);
    document.getElementById('kpiAvgRating').textContent = fmt3(DATA.avgRating);
    document.getElementById('kpiRatingRange').textContent = 'Range: ' + fmt1(DATA.minRating) + '–' + fmt1(DATA.maxRating);
    document.getElementById('kpiAvgReviews').textContent = fmtInt(DATA.avgReviews);
    document.getElementById('kpiReviewsRange').textContent = 'Range: ' + fmtInt(DATA.minReviews) + '–' + fmtInt(DATA.maxReviews);
    document.getElementById('kpiCorr').textContent = fmt3(DATA.corrAll);
    document.getElementById('corrInline').textContent = fmt3(DATA.corrAll);

    // Bullets
    (function(){{
      const labels = DATA.priceBuckets.labels;
      const counts = DATA.priceBuckets.counts;
      const ranked = labels.map((l,i)=>({{l:l,c:counts[i]}})).sort((a,b)=>b.c-a.c);
      const share=(c)=>100*c/DATA.nRows;

      const top1=ranked[0], top2=ranked[1];
      const i50=labels.indexOf('50+');
      const i20=labels.indexOf('20-29');
      const share2009=DATA.priceBucketsByYear['2009'].map(c=>c/50);
      const share2019=DATA.priceBucketsByYear['2019'].map(c=>c/50);

      const over=document.getElementById('overviewBullets');
      [
        'Mid-price dominance: $' + top1.l + ' is ' + fmt1(share(top1.c)) + '% and $' + top2.l + ' is ' + fmt1(share(top2.c)) + '% (combined ' + fmt1(share(top1.c+top2.c)) + '%).',
        'Decade benchmarks: avg price ' + fmtUSD(DATA.avgPrice) + '; avg rating ' + fmt3(DATA.avgRating) + '; avg reviews ' + fmtInt(DATA.avgReviews) + '; ' + fmtInt(DATA.uniqueBooks) + ' unique titles; ' + fmtInt(DATA.uniqueAuthors) + ' unique authors.',
        'Premium is rare: only ' + fmtInt(counts[i50]) + ' entries are priced $50+ across 2009–2019.',
        'Shift toward lower price in 2019: $20–$29 share drops from ' + fmt1(100*share2009[i20]) + '% (2009) to ' + fmt1(100*share2019[i20]) + '% (2019); $30–$49 and $50+ are 0 entries in 2019.'
      ].forEach(t=>{{const li=document.createElement('li'); li.textContent=t; over.appendChild(li);}});

      const gF=DATA.byGenre['Fiction'];
      const gN=DATA.byGenre['Non Fiction'];
      const genreBullets=document.getElementById('genreBullets');
      [
        'Non Fiction prices higher (avg ' + fmtUSD(gN.avgPrice) + ') than Fiction (avg ' + fmtUSD(gF.avgPrice) + ') but rates slightly lower (' + fmt3(gN.avgRating) + ' vs ' + fmt3(gF.avgRating) + ').',
        'Fiction has higher average review volume (' + fmtInt(gF.avgReviews) + ' vs ' + fmtInt(gN.avgReviews) + '), indicating stronger engagement dynamics in Fiction bestsellers.',
        'Both genres show weak negative price–rating correlation (Fiction r=' + fmt3(DATA.corrByGenre['Fiction']) + '; Non Fiction r=' + fmt3(DATA.corrByGenre['Non Fiction']) + ').'
      ].forEach(t=>{{const li=document.createElement('li'); li.textContent=t; genreBullets.appendChild(li);}});

      const trendBullets=document.getElementById('trendBullets');
      const findYear=(y)=>DATA.byYear.find(d=>d.Year===y);
      const d2015=DATA.yoy.find(d=>d.Year===2015);
      const d2012=DATA.yoy.find(d=>d.Year===2012);
      const d2019=DATA.yoy.find(d=>d.Year===2019);
      [
        '2015 is the major pricing inflection: avg price falls from ' + fmtUSD(findYear(2014).avgPrice) + ' to ' + fmtUSD(findYear(2015).avgPrice) + ' (YoY Δ ' + fmtUSD(d2015.dPrice) + ').',
        '2012 is the major engagement inflection: avg reviews rise by ' + fmtInt(d2012.dReviews) + ' vs 2011 (to ' + fmtInt(findYear(2012).avgReviews) + ').',
        '2019 is the major sentiment inflection: largest YoY rating increase (Δ ' + fmt3(d2019.dRating) + ') and the highest avg rating (' + fmt3(findYear(2019).avgRating) + ').',
        'After 2015, average prices remain lower (≈$10–$13) while average ratings stay high (≥' + fmt3(findYear(2015).avgRating) + ').'
      ].forEach(t=>{{const li=document.createElement('li'); li.textContent=t; trendBullets.appendChild(li);}});

      const reco=document.getElementById('recoList');
      const topAuthors=DATA.topAuthors.slice(0,5).map(a=>a.Author).join(', ');
      [
        {{title:'Optimize price for conversion/margin, not rating lift.', body:'Overall Pearson r is ' + fmt3(DATA.corrAll) + ' (weak negative), so price is not a reliable satisfaction lever.'}},
        {{title:'Target the $5–$14 corridor for bestseller velocity.', body:'$5–$9 and $10–$14 are the two largest price bands, together ' + fmt1(100*(counts[labels.indexOf('5-9')]+counts[labels.indexOf('10-14')])/DATA.nRows) + '% of entries.'}},
        {{title:'Premium Non Fiction can work, but justify value explicitly.', body:'Non Fiction averages higher price (' + fmtUSD(gN.avgPrice) + ') with slightly lower ratings than Fiction.'}},
        {{title:'Invest in Fiction franchises/series to compound engagement.', body:'Fiction averages ' + fmtInt(gF.avgReviews) + ' reviews vs ' + fmtInt(gN.avgReviews) + ' in Non Fiction.'}},
        {{title:'Treat 2015-style repricing as a playbook option.', body:'The largest price drop (2015, Δ ' + fmtUSD(d2015.dPrice) + ') did not coincide with rating collapse; ratings remained high and improved later.'}},
        {{title:'Operationalize repeat-author scouting.', body:'Top repeat authors (e.g., ' + topAuthors + ') represent durable catalog assets; use appearances + ratings for prioritization.'}}
      ].forEach(r=>{{const li=document.createElement('li'); li.innerHTML='<strong>' + r.title + '</strong><div class="muted" style="margin-top:4px">' + r.body + '</div>'; reco.appendChild(li);}});
    }})();

    // Tables
    (function(){{
      const corrBody=document.getElementById('corrTable');
      [
        {{slice:'Overall', r: DATA.corrAll, interp:'Weak negative relationship.'}},
        {{slice:'Fiction', r: DATA.corrByGenre['Fiction'], interp:'Weak negative.'}},
        {{slice:'Non Fiction', r: DATA.corrByGenre['Non Fiction'], interp:'Weak negative.'}}
      ].forEach(x=>{{const tr=document.createElement('tr'); tr.innerHTML='<td>' + x.slice + '</td><td class="num">' + fmt3(x.r) + '</td><td>' + x.interp + '</td>'; corrBody.appendChild(tr);}});

      const genreBody=document.getElementById('genreTable');
      ['Fiction','Non Fiction'].forEach(g=>{{const s=DATA.byGenre[g]; const tr=document.createElement('tr'); tr.innerHTML='<td>' + g + '</td><td class="num">' + fmtInt(s.count) + '</td><td class="num">' + fmtUSD(s.avgPrice) + '</td><td class="num">' + fmt3(s.avgRating) + '</td><td class="num">' + fmtInt(s.avgReviews) + '</td><td class="num">' + fmtInt(s.uniqueAuthors) + '</td>'; genreBody.appendChild(tr);}});

      const inflBody=document.getElementById('inflectionTable');
      DATA.yoy.forEach(d=>{{const tr=document.createElement('tr'); tr.innerHTML='<td>' + d.Year + '</td><td class="num">' + fmtUSD(d.dPrice) + '</td><td class="num">' + fmt3(d.dRating) + '</td><td class="num">' + fmtInt(d.dReviews) + '</td>'; inflBody.appendChild(tr);}});

      const authorBody=document.getElementById('authorTable');
      DATA.topAuthors.forEach(a=>{{const tr=document.createElement('tr'); tr.innerHTML='<td>' + a.Author + '</td><td class="num">' + fmtInt(a.appearances) + '</td><td class="num">' + fmtInt(a.uniqueTitles) + '</td><td class="num">' + fmtUSD(a.avgPrice) + '</td><td class="num">' + fmt3(a.avgRating) + '</td><td class="num">' + fmtInt(a.avgReviews) + '</td>'; authorBody.appendChild(tr);}});
    }})();

    // Charts
    Chart.defaults.color = getComputedStyle(document.documentElement).getPropertyValue('--text').trim();
    Chart.defaults.font.family = getComputedStyle(document.body).fontFamily;
    const gridColor = getComputedStyle(document.documentElement).getPropertyValue('--grid').trim();
    const nfColor = getComputedStyle(document.documentElement).getPropertyValue('--nf').trim();
    const ficColor = getComputedStyle(document.documentElement).getPropertyValue('--fic').trim();
    const accent = getComputedStyle(document.documentElement).getPropertyValue('--accent').trim();

    new Chart(document.getElementById('priceBuckets'), {{
      type: 'bar',
      data: {{labels: DATA.priceBuckets.labels.map(l=>'$' + l), datasets: [{{label:'Entries', data: DATA.priceBuckets.counts, backgroundColor:'rgba(105,179,255,.35)', borderColor:'rgba(105,179,255,.9)', borderWidth:1, borderRadius:8}}]}},
      options: {{plugins:{{legend:{{display:false}}}}, scales:{{x:{{grid:{{display:false}}}}, y:{{grid:{{color:gridColor}}}}}}}}
    }});

    new Chart(document.getElementById('scatterAll'), {{
      type: 'scatter',
      data: {{datasets: [
        {{label:'Fiction', data: DATA.scatterSample.filter(p=>p.g==='Fiction').map(p=>({{x:p.x,y:p.y}})), backgroundColor:'rgba(142,240,197,.55)', borderColor: ficColor, pointRadius:3}},
        {{label:'Non Fiction', data: DATA.scatterSample.filter(p=>p.g==='Non Fiction').map(p=>({{x:p.x,y:p.y}})), backgroundColor:'rgba(105,179,255,.45)', borderColor: nfColor, pointRadius:3}}
      ]}},
      options: {{plugins:{{title:{{display:true, text:'Pearson r (full data): ' + fmt3(DATA.corrAll)}}, legend:{{position:'bottom'}}}}, scales:{{x:{{grid:{{color:gridColor}}, title:{{display:true, text:'Price (USD)'}}}}, y:{{grid:{{color:gridColor}}, title:{{display:true, text:'User Rating'}}, suggestedMin:DATA.minRating, suggestedMax:DATA.maxRating}}}}}}
    }});

    const years = DATA.byYear.map(d=>d.Year);
    new Chart(document.getElementById('trendOverall'), {{
      type:'line',
      data: {{labels: years, datasets:[
        {{label:'Avg Price (USD)', data: DATA.byYear.map(d=>d.avgPrice), yAxisID:'yPrice', borderColor: accent, backgroundColor:'rgba(105,179,255,.15)', tension:.25, fill:true, pointRadius:3}},
        {{label:'Avg Rating', data: DATA.byYear.map(d=>d.avgRating), yAxisID:'yRating', borderColor:'rgba(255,184,107,.95)', tension:.25, fill:false, pointRadius:3}}
      ]}},
      options: {{plugins:{{legend:{{position:'bottom'}}}}, scales:{{x:{{grid:{{color:gridColor}}}}, yPrice:{{position:'left', grid:{{color:gridColor}}, title:{{display:true, text:'Avg Price'}}}}, yRating:{{position:'right', grid:{{display:false}}, title:{{display:true, text:'Avg Rating'}}, min:4.5, max:4.75}}}}}}
    }});

    new Chart(document.getElementById('trendReviews'), {{
      type:'line',
      data: {{labels: years, datasets:[{{label:'Avg Reviews', data: DATA.byYear.map(d=>d.avgReviews), borderColor:'rgba(142,240,197,.95)', backgroundColor:'rgba(142,240,197,.12)', tension:.25, fill:true, pointRadius:3}}]}},
      options: {{plugins:{{legend:{{position:'bottom'}}}}, scales:{{x:{{grid:{{color:gridColor}}}}, y:{{grid:{{color:gridColor}}, title:{{display:true, text:'Avg Reviews'}}}}}}}}
    }});

    function lineChart(id, yTitle, seriesKey){{
      new Chart(document.getElementById(id), {{
        type:'line',
